import random
opciones = ["piedra", "papel", "tijera"]
puntos_tu = 0
puntos_compu = 0
def quien_gana(tu, compu):
    if tu == compu:
        return "empate"
    if tu == "piedra" and compu == "tijera":
        return "tu"
    if tu == "papel" and compu == "piedra":
        return "tu"
    if tu == "tijera" and compu == "papel":
        return "tu"
    return "compu"
print("¡Piedra, papel o tijera! Jugamos 3 rondas.")
for ronda in range(1, 4):
    print("Ronda", ronda)
    tu = input("Elige piedra, papel o tijera: ").lower()
    while tu not in opciones:
        tu = input("No entendí. Escribe piedra, papel o tijera: ").lower()
    compu = random.choice(opciones)
    print("La computadora eligió", compu)
    resultado = quien_gana(tu, compu)
    if resultado == "tu":
        puntos_tu = puntos_tu + 1
        print("¡Ganaste la ronda!")
    elif resultado == "compu":
        puntos_compu = puntos_compu + 1
        print("La computadora gana la ronda.")
    else:
        print("Empate.")
print("Marcador final:", puntos_tu, "a", puntos_compu)
if puntos_tu > puntos_compu:
    print("¡Ganaste el juego!")
elif puntos_compu > puntos_tu:
    print("Ganó la computadora. ¡Revancha!")
else:
    print("¡Empate!")
